"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["53456"],{2550(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.portal.origem_indisponivel","status":503,"titulo":"Dados do certame temporariamente indispon\xedveis"},"descricao":{"codigo":"uniplus.portal.origem_indisponivel","requisitos":[],"oQueAconteceu":["A p\xe1gina p\xfablica de um certame re\xfane o detalhe publicado pelo m\xf3dulo de Sele\xe7\xe3o e a linha do tempo de atos de Publica\xe7\xf5es. O detalhe do certame n\xe3o p\xf4de ser obtido agora: o m\xf3dulo de Sele\xe7\xe3o n\xe3o respondeu a tempo, respondeu com falha ou devolveu um conte\xfado incompleto. A resposta traz o detalhe \xabOs dados do certame est\xe3o temporariamente indispon\xedveis.\xbb e nenhuma p\xe1gina \xe9 entregue. A configura\xe7\xe3o publicada de um certame tem efeito jur\xeddico, e uma retifica\xe7\xe3o n\xe3o pode ficar encoberta, por isso o sistema n\xe3o serve no lugar uma vers\xe3o guardada de antes.","O estado \xe9 transit\xf3rio. A resposta traz o cabe\xe7alho `Retry-After`, com o n\xfamero de segundos a esperar antes de tentar de novo, e n\xe3o \xe9 guardada em nenhum cache. Se s\xf3 a linha do tempo de atos estiver indispon\xedvel, esta falha n\xe3o ocorre: a p\xe1gina sai com os dados do certame e um aviso de que a linha do tempo est\xe1 incompleta."],"comoResolver":["Aguarde o tempo indicado em `Retry-After` e repita a consulta. Se a indisponibilidade persistir por mais do que alguns minutos, acione o suporte do Uni+ informando o hor\xe1rio da tentativa e o identificador leg\xedvel do certame consultado."],"ondeAparece":["Consulta da p\xe1gina p\xfablica do certame"]},"modulo":{"id":"portal","nome":"Portal","assunto":"Origem indisponivel"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"2b5f8240ef92ed3147f41ca40a325e729f45c7bd"}}')}}]);